// 다른 과목 레슨 데이터 (간략화된 버전)
const allSubjectLessons: { [subject: string]: { [day: number]: LessonData } } = {
  'social-culture': socialCultureLessons,
  'life-ethics': lifeEthicsLessons,
  'ethics-thought': ethicsThoughtLessons,
  'korean-geography': koreanGeographyLessons,
  'world-geography': worldGeographyLessons,
  'politics-law': politicsLawLessons,
  'east-asian-history': eastAsianHistoryLessons,
  'world-history': worldHistoryLessons,
  'economics': economicsLessons,
  'physics-1': physics1Lessons,
  'physics-2': physics2Lessons,
  'chemistry-1': chemistry1Lessons,
  'chemistry-2': chemistry2Lessons,
  'biology-1': biology1Lessons,
  'biology-2': biology2Lessons,
  'earth-science-1': earthScience1Lessons,
  'earth-science-2': earthScience2Lessons,
};

export default function ExplorationLessonPage() {
  const params = useParams();
  const subject = params.subject as string;
  const day = Number(params.day);

  const subjectData = subjectInfo[subject];
  const lessons = allSubjectLessons[subject] || {};
  const lesson = lessons[day];

  const [copied, setCopied] = useState(false);
  const [selectedAI, setSelectedAI] = useState<'claude' | 'chatgpt'>('claude');
  const [completed, setCompleted] = useState(false);
  const [showConfetti, setShowConfetti] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem(`exploration-${subject}-completed`);
    if (saved) {
      const completedDays = JSON.parse(saved);
      setCompleted(completedDays.includes(day));
    }
  }, [subject, day]);

  const copyPrompt = async () => {
    if (!lesson) return;
    await navigator.clipboard.writeText(lesson.prompt);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const openAI = async () => {
    if (!lesson) return;
    await navigator.clipboard.writeText(lesson.prompt);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    const url = selectedAI === 'claude' ? 'https://claude.ai/new' : 'https://chat.openai.com/';
    window.open(url, '_blank');
  };

  const markComplete = () => {
    setCompleted(true);
    setShowConfetti(true);

    const saved = localStorage.getItem(`exploration-${subject}-completed`);
    const completedDays = saved ? JSON.parse(saved) : [];
    if (!completedDays.includes(day)) {
      completedDays.push(day);
      localStorage.setItem(`exploration-${subject}-completed`, JSON.stringify(completedDays));
    }

    setTimeout(() => setShowConfetti(false), 3000);
  };

  if (!subjectData) {
    return <div className="min-h-screen flex items-center justify-center">과목을 찾을 수 없습니다.</div>;
  }

  // 레슨 데이터가 없으면 기본 템플릿 사용
  const defaultLesson: LessonData = {
    title: `Day ${day} 학습`,
    desc: '학습 내용 준비 중',
    prompt: `${subjectData.name} Day ${day} 학습 내용을 알려주세요.\n\n1. 핵심 개념 설명\n2. 중요 용어 정리\n3. 연습 문제 5개\n4. 실전 팁`,
    funFact: '꾸준히 학습하면 반드시 실력이 늘어요!',
    challenge: '오늘 배운 내용을 복습해보세요!',
    youtubeKeyword: `${subjectData.name} ${day}일차 강의`,
    keywords: [],
  };

  const currentLesson = lesson || defaultLesson;

  return (
    <div className={`min-h-screen bg-gradient-to-br from-slate-50 to-${subjectData.colorLight}-50`}>
      {showConfetti && (
        <div className="fixed inset-0 pointer-events-none z-50">
          {[...Array(50)].map((_, i) => (
            <div key={i} className="absolute animate-bounce" style={{
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
              animationDelay: `${Math.random() * 2}s`,
              fontSize: '24px'
            }}>
              {['🎉', '⭐', '🏆', '✨', '📚'][Math.floor(Math.random() * 5)]}
            </div>
          ))}
        </div>
      )}

      <nav className="bg-slate-900 text-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center">
              <Link href="/" className="flex items-center">
                <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center mr-2">
                  <Brain className="w-5 h-5 text-white" />
                </div>
                <span className="text-xl font-bold">UTTEC Edu</span>
              </Link>
            </div>
          </div>
        </div>
      </nav>

      <div className="bg-white border-b">
        <div className="max-w-7xl mx-auto px-4 py-3">
          <div className="flex items-center gap-2 text-sm text-gray-600">
            <Link href="/course/exploration" className="hover:text-blue-600">탐구영역</Link>
            <ChevronRight className="w-4 h-4" />
            <Link href={`/course/exploration/${subject}`} className="hover:text-blue-600">{subjectData.name}</Link>
            <ChevronRight className="w-4 h-4" />
            <span className="text-gray-900 font-medium">Day {day}</span>
          </div>
        </div>
      </div>

      <section className={`bg-gradient-to-r ${subjectData.color} text-white py-8`}>
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-14 h-14 bg-white/20 rounded-full flex items-center justify-center">
                <span className="text-2xl font-bold">D{day}</span>
              </div>
              <div>
                <h1 className="text-2xl font-bold">{currentLesson.title}</h1>
                <p className="text-white/80">{currentLesson.desc}</p>
              </div>
            </div>
            {completed && (
              <div className="flex items-center gap-2 bg-white/20 px-4 py-2 rounded-full">
                <Trophy className="w-5 h-5" />
                <span className="font-medium">완료!</span>
              </div>
            )}
          </div>
        </div>
      </section>

      <main className="max-w-4xl mx-auto px-4 py-8">
        {/* 학습 팁 */}
        <div className="bg-gradient-to-r from-amber-50 to-yellow-50 border border-amber-200 rounded-xl p-4 mb-6">
          <div className="flex items-start gap-3">
            <Lightbulb className="w-6 h-6 text-amber-500 flex-shrink-0 mt-1" />
            <div>
              <p className="font-medium text-amber-800 mb-1">학습 팁</p>
              <p className="text-amber-700 text-sm">AI에게 "더 쉽게 설명해줘", "예시를 더 들어줘", "문제 더 만들어줘"라고 요청할 수 있어요!</p>
            </div>
          </div>
        </div>

        {/* AI 프롬프트 */}
        <div className="bg-white rounded-2xl shadow-lg p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
              <Target className="w-5 h-5 text-indigo-500" />
              AI 프롬프트
            </h2>
            <select
              value={selectedAI}
              onChange={(e) => setSelectedAI(e.target.value as 'claude' | 'chatgpt')}
              className="text-sm border rounded-lg px-3 py-1.5"
            >
              <option value="claude">Claude</option>
              <option value="chatgpt">ChatGPT</option>
            </select>
          </div>

          <div className="bg-gray-50 rounded-xl p-4 mb-4 font-mono text-sm whitespace-pre-wrap max-h-64 overflow-y-auto">
            {currentLesson.prompt}
          </div>

          <div className="flex gap-3">
            <button onClick={copyPrompt} className={`flex-1 py-3 rounded-xl font-medium transition flex items-center justify-center gap-2 ${copied ? 'bg-green-500 text-white' : 'bg-indigo-500 hover:bg-indigo-600 text-white'}`}>
              {copied ? <><Check className="w-5 h-5" /> 복사됨!</> : <><Copy className="w-5 h-5" /> 프롬프트 복사</>}
            </button>
            <button onClick={openAI} className="flex-1 bg-slate-800 hover:bg-slate-900 text-white py-3 rounded-xl font-medium transition flex items-center justify-center gap-2">
              <Sparkles className="w-5 h-5" />
              {selectedAI === 'claude' ? 'Claude' : 'ChatGPT'} 열기
            </button>
          </div>
        </div>

        {/* 핵심 키워드 */}
        {currentLesson.keywords && currentLesson.keywords.length > 0 && (
          <div className="bg-white rounded-2xl shadow-lg p-6 mb-6">
            <h3 className="font-bold text-gray-900 mb-4 flex items-center gap-2">
              <BookOpen className="w-5 h-5 text-indigo-500" />
              핵심 키워드
            </h3>
            <div className="space-y-3">
              {currentLesson.keywords.map((keyword, index) => {
                // 문자열인 경우와 Keyword 객체인 경우 구분
                if (typeof keyword === 'string') {
                  return (
                    <div key={index} className="bg-gray-50 rounded-xl px-4 py-2 inline-block mr-2 mb-2">
                      <span className="font-medium text-indigo-600">{keyword}</span>
                    </div>
                  );
                }
                return (
                  <div key={index} className="bg-gray-50 rounded-xl p-4">
                    <div className="flex items-center justify-between mb-2">
                      <span className="font-bold text-indigo-600">{keyword.term}</span>
                      <a
                        href={`https://www.google.com/search?q=${encodeURIComponent(keyword.searchQuery)}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-xs text-gray-500 hover:text-indigo-600 flex items-center gap-1"
                      >
                        더 알아보기 <ExternalLink className="w-3 h-3" />
                      </a>
                    </div>
                    <p className="text-gray-700 text-sm">{keyword.definition}</p>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* 재미있는 사실 & 도전 과제 */}
        <div className="grid md:grid-cols-2 gap-4 mb-6">
          <div className="bg-gradient-to-br from-purple-50 to-pink-50 rounded-xl p-5 border border-purple-100">
            <h3 className="font-bold text-purple-800 mb-2 flex items-center gap-2">
              <Star className="w-5 h-5 text-purple-500" />
              오늘의 재미있는 사실
            </h3>
            <p className="text-purple-700 text-sm">{currentLesson.funFact}</p>
          </div>
          <div className="bg-gradient-to-br from-green-50 to-emerald-50 rounded-xl p-5 border border-green-100">
            <h3 className="font-bold text-green-800 mb-2 flex items-center gap-2">
              <Trophy className="w-5 h-5 text-green-500" />
              도전 과제
            </h3>
            <p className="text-green-700 text-sm">{currentLesson.challenge}</p>
          </div>
        </div>

        {/* YouTube 링크 */}
        {currentLesson.youtubeKeyword && (
          <div className="bg-gradient-to-br from-red-50 to-orange-50 rounded-xl p-5 border border-red-100 mb-6">
            <h3 className="font-bold text-red-800 mb-3 flex items-center gap-2">
              <Youtube className="w-5 h-5 text-red-500" />
              관련 강의 영상
            </h3>
            <p className="text-red-700 text-sm mb-3">
              이 주제에 대한 강의 영상을 YouTube에서 찾아보세요!
            </p>
            <a
              href={`https://www.youtube.com/results?search_query=${encodeURIComponent(currentLesson.youtubeKeyword)}`}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-2 bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-lg transition font-medium"
            >
              <Youtube className="w-4 h-4" />
              YouTube에서 "{currentLesson.youtubeKeyword}" 검색
              <ExternalLink className="w-4 h-4" />
            </a>
          </div>
        )}

        {/* 학습 완료 버튼 */}
        {!completed && (
          <button onClick={markComplete} className="w-full bg-gradient-to-r from-green-500 to-emerald-500 hover:from-green-600 hover:to-emerald-600 text-white py-4 rounded-xl font-bold text-lg transition flex items-center justify-center gap-2">
            <Trophy className="w-6 h-6" />
            학습 완료!
          </button>
        )}

        {/* 이전/다음 네비게이션 */}
        <div className="flex justify-between mt-8">
          {day > 1 ? (
            <Link href={`/course/exploration/${subject}/lesson/${day - 1}`} className="flex items-center gap-2 text-gray-600 hover:text-indigo-600 transition">
              <ChevronLeft className="w-5 h-5" />
              <span>Day {day - 1}</span>
            </Link>
          ) : <div />}
          {day < 45 ? (
            <Link href={`/course/exploration/${subject}/lesson/${day + 1}`} className="flex items-center gap-2 text-gray-600 hover:text-indigo-600 transition">
              <span>Day {day + 1}</span>
              <ChevronRight className="w-5 h-5" />
            </Link>
          ) : (
            <Link href={`/course/exploration/${subject}`} className="flex items-center gap-2 text-indigo-600 font-medium">
              <span>코스 완료!</span>
              <Trophy className="w-5 h-5" />
            </Link>
          )}
        </div>
      </main>

      <footer className="bg-slate-900 text-gray-400 py-8">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <p className="text-sm">© 2025 UTTEC Lab. All rights reserved.</p>
        </div>
      </footer>
    </div>
  );
}
